void Editor::loadDynamicsPreferences(){try{const auto path=dynamicsPreferenceOverride_.empty()?palettePreferencePath().parent_path()/"brush-dynamics-v6.txt":dynamicsPreferenceOverride_;std::ifstream in(path);std::string version;dynamics::Settings settings;int sensor,curve,inverse;if(!(in>>version>>settings.gradientDither)||version!="brush-dynamics-v6")return;for(auto& m:settings.effects){if(!(in>>sensor>>m.outputMin>>m.outputMax>>m.inputMin>>m.inputMax>>curve>>inverse))return;m.sensor=dynamics::Sensor(sensor);m.curve=dynamics::Curve(curve);m.inverse=inverse!=0;}brushDynamics_=dynamics::normalize(settings);}catch(...){status_=U"动态偏好读取失败";}}
