void Editor::observeDynamicsInput(ui::Message* msg){if(msg->type()==ui::kFocusLeaveMessage){dynamicsSpeed_.reset();dynamicsPreviousPressure_.reset();dynamicsPressureProved_=false;dynamicsInput_.pressureAvailable=false;return;}if(msg->type()!=ui::kMouseDownMessage&&msg->type()!=ui::kMouseMoveMessage&&msg->type()!=ui::kMouseUpMessage)return;auto m=static_cast<ui::MouseMessage*>(msg);if(msg->type()==ui::kMouseDownMessage){dynamicsSpeed_.reset();dynamicsPreviousPressure_.reset();dynamicsPressureProved_=false;}const bool pen=m->pointerType()==os::PointerType::Pen||m->pointerType()==os::PointerType::Eraser,touch=m->pointerType()==os::PointerType::Touch;const bool available=dynamics::reliablePressure(pen,touch,m->pressure(),dynamicsPreviousPressure_,dynamicsPressureProved_);if(available)dynamicsPressureProved_=true;dynamicsInput_.pressure=m->pressure();dynamicsInput_.pressureAvailable=available&&(!pen||runtimePreferences_.flag("tablet.tablet.pressureEnabled"));dynamicsPreviousPressure_=m->pressure();const auto now=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now().time_since_epoch()).count();dynamicsInput_.speed=dynamics::trackSpeed(dynamicsSpeed_,double(m->position().x)/uiScale,double(m->position().y)/uiScale,now);if(dynamicsPopup_&&dynamicsPopup_->isVisible()&&dynamicsChart_)dynamicsChart_->invalidate();}
